CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tables (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, description TEXT NOT NULL DEFAULT '', owner_user_id UUID NOT NULL REFERENCES users(id), state VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','finalized')), archived_at TIMESTAMPTZ, version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tables_active_idx ON tables(archived_at, updated_at DESC);
CREATE TABLE IF NOT EXISTS table_rows (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), table_id UUID NOT NULL REFERENCES tables(id) ON DELETE CASCADE, position INTEGER NOT NULL, height INTEGER NOT NULL DEFAULT 52, UNIQUE(table_id,position));
CREATE TABLE IF NOT EXISTS table_columns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), table_id UUID NOT NULL REFERENCES tables(id) ON DELETE CASCADE, position INTEGER NOT NULL, label VARCHAR(160) NOT NULL DEFAULT '', width INTEGER NOT NULL DEFAULT 210, UNIQUE(table_id,position));
CREATE TABLE IF NOT EXISTS cells (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), table_id UUID NOT NULL REFERENCES tables(id) ON DELETE CASCADE, row_id UUID NOT NULL REFERENCES table_rows(id) ON DELETE CASCADE, column_id UUID NOT NULL REFERENCES table_columns(id) ON DELETE CASCADE, content TEXT NOT NULL DEFAULT '', style JSONB NOT NULL DEFAULT '{}', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(row_id,column_id));
CREATE TABLE IF NOT EXISTS images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), table_id UUID NOT NULL REFERENCES tables(id) ON DELETE CASCADE, cell_id UUID REFERENCES cells(id) ON DELETE SET NULL, object_key TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes <= 10485760), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS edit_locks (table_id UUID PRIMARY KEY REFERENCES tables(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_heartbeat TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS edit_locks_heartbeat_idx ON edit_locks(last_heartbeat);
CREATE TABLE IF NOT EXISTS history (id BIGSERIAL PRIMARY KEY, table_id UUID NOT NULL REFERENCES tables(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, event_type VARCHAR(80) NOT NULL, target TEXT NOT NULL DEFAULT '', details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS history_table_created_idx ON history(table_id, created_at DESC);
